-- V11 — restore the Flow Variant dropdown on the front gate.
-- The page hardcoded workflowCode="M10.TankerInbound"; WorkflowActionButton
-- resolves {{form.flowVariant}} (its docstring's own example), so a flowVariant
-- select feeding workflowCode was the intended design. Adds it (10 real front-gate
-- workflows) + points Create Gate Pass at {{form.flowVariant}}. Product (-1).
UPDATE page_version pv JOIN page_definition pd ON pd.id=pv.page_id
SET pv.body_json='{"kind":"layout","schemaVersion":2,"slug":"aria:front-gate-create","title":"Front Gate — Tanker Intake","status":"published","version":1,"roles":["FrontGate","TenantAdmin"],"dataSources":[],"streams":[],"entity":"GatePass","layout":[{"kind":"Grid","columns":12,"gap":16,"children":[{"kind":"Section","title":"New Vehicle Intake","span":12,"subtitle":"Capture the vehicle + driver at the gate, then Create Gate Pass to start the tanker-inbound flow.","children":[{"kind":"Form","submitLabel":"","bindings":{"fields":[{"name":"flowVariant","label":"Flow Variant","type":"select","required":true,"options":[{"label":"Tanker Inbound (RM oil receipt)","value":"M10.TankerInbound"},{"label":"Tanker Outbound (bulk oil dispatch)","value":"M10.TankerOutbound"},{"label":"Packing — Loading (packed goods out)","value":"M10.PackLoading"},{"label":"Packing — Unload (packed goods in)","value":"M10.PackUnload"},{"label":"FG Loading (finished goods out)","value":"M10.FGLoading"},{"label":"Return Stock In","value":"M10.ReturnStockIn"},{"label":"Internal Transfer In","value":"M10.IntTransferIn"},{"label":"Internal Transfer Out","value":"M10.IntTransferOut"},{"label":"Third Party In","value":"M10.ThirdPartyIn"},{"label":"Third Party Out","value":"M10.ThirdPartyOut"}]},{"name":"vehicleNo","label":"Vehicle No","type":"text","required":true,"placeholder":"TN-46-CJ-0001"},{"name":"driverName","label":"Driver Name","type":"text","required":true,"placeholder":"e.g. Suresh Kumar"},{"name":"driverPhone","label":"Driver Phone","type":"tel","placeholder":"+91 90000 00000"},{"name":"sourceParty","label":"Coming From (Vendor)","type":"text","placeholder":"e.g. ABC Edible Oil"}]},"children":[{"kind":"WorkflowActionButton","label":"Create Gate Pass","action":"workflow.transition","workflowCode":"{{form.flowVariant}}","targetState":"GATE_PASS_CREATED","trigger":"page.submitted","color":"primary"}]}]},{"kind":"Section","title":"Gate Passes In Progress","span":12,"subtitle":"Vehicles you have logged that are moving through parking, weighment and QC.","children":[{"kind":"WorkflowQueueList","persona":"frontgate","pageSize":25,"cardFields":["vehicleNo","driverName","gpNumber","currentState"]}]}]}]}'
WHERE pd.code='aria:front-gate-create' AND pv.id=pd.current_version_id;
